const DEFAULT_PAGE_TITLE_ID =
  'ValueCreation.PerformanceTool.pageTitle.brandPower';

const PAGE_TITLE_BY_KPI: Record<string, string> = {
  volume: 'ValueCreation.PerformanceTool.pageTitle.volume',
  nr: 'ValueCreation.PerformanceTool.pageTitle.netRevenue',
  cores: 'ValueCreation.PerformanceTool.pageTitle.cores',
  market_share: 'ValueCreation.PerformanceTool.pageTitle.marketShare',
  power: 'ValueCreation.PerformanceTool.pageTitle.brandPower',
};

export function getPageTitleByKpi(kpi?: string): string {
  if (!kpi) return DEFAULT_PAGE_TITLE_ID;
  return PAGE_TITLE_BY_KPI[kpi] ?? DEFAULT_PAGE_TITLE_ID;
}
